<?php $page=$modulePageData; ?>
<?php if($page['flash']): ?><p class="notice notice-success" role="status"><?= inventoryEscape($page['flash']) ?></p><?php endif; ?>
<?php if($page['errors']): ?><div class="notice notice-error" role="alert"><?php foreach($page['errors'] as $error): ?><p><?= inventoryEscape($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if($page['available']): ?>
<section aria-labelledby="variants-title">
<div class="contact-toolbar"><div><p class="eyebrow">INVENTARIO</p><h1 id="variants-title"><?= $page['view']==='form'?'Nueva variante':'Variantes del producto' ?></h1><p class="section-subtitle"><?= $page['view']==='form'?'Elige el producto principal y escribe el nombre de la variante.':'Productos relacionados, con sus propios precios y existencias.' ?></p></div><?php if($page['view']==='list'): ?><a class="contact-button contact-button-primary" href="variantes.php?new=1<?= $page['parentId']?'&amp;parent_id='.(int)$page['parentId']:'' ?>">+ Nueva variante</a><?php endif; ?></div>
<form class="contact-filters" method="get"><label>Buscar variante<input type="search" name="q" maxlength="160" placeholder="Nombre de la variante o producto principal" value="<?= inventoryEscape($page['search']) ?>"></label><label>Producto principal<select name="parent_id"><option value="">Todos los productos</option><?php foreach($page['parents'] as $parent): ?><option value="<?= (int)$parent['id'] ?>" <?= $page['parentId']===(int)$parent['id']?'selected':'' ?>><?= inventoryEscape($parent['name']) ?></option><?php endforeach; ?></select></label><button class="contact-button" type="submit">Buscar</button><a class="contact-button" href="variantes.php">Limpiar</a></form>
<div class="contact-table-wrap" role="region" aria-label="Listado de variantes" tabindex="0"><table class="contact-table"><thead><tr><th>Variante</th><th>Producto principal</th><th>Precio</th><th>Acción</th></tr></thead><tbody><?php foreach($page['variants'] as $variant): ?><tr><td><a class="contact-name" href="index.php?id=<?= (int)$variant['id'] ?>"><?= inventoryEscape($variant['name']) ?></a></td><td><a class="inline-link" href="index.php?id=<?= (int)$variant['parent_product_id'] ?>#product-page-variants"><?= inventoryEscape($variant['parent_name']) ?></a></td><td><?= inventoryEscape($variant['sale_price'].' '.$variant['currency_code']) ?></td><td><a class="inline-link" href="index.php?id=<?= (int)$variant['id'] ?>">Editar variante</a></td></tr><?php endforeach; ?><?php if(!$page['variants']): ?><tr><td colspan="4" class="contact-empty">No hay variantes para este filtro. Crea una y relaciónala con su producto principal.</td></tr><?php endif; ?></tbody></table></div>
<nav class="contact-pagination" aria-label="Páginas de variantes"><span><?= $page['total'] ?> variantes · Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach(['Anterior'=>$page['currentPage']-1,'Siguiente'=>$page['currentPage']+1] as $label=>$number): ?><?php if($number>=1&&$number<=$page['pages']): ?><a class="contact-button" href="variantes.php?<?= inventoryEscape(http_build_query(['q'=>$page['search'],'parent_id'=>$page['parentId'],'page'=>$number])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav>
</section>
<?php endif; ?>
